package cn.mop.persistence;
import org.junit.jupiter.api.Test;
import java.util.*;
import java.nio.charset.StandardCharsets;
import static org.junit.jupiter.api.Assertions.*;
class BackupVersionMigrationTest {
 @Test void explicitV49RequiresV48AndReadOnlyNeverApplies()throws Exception{BackupVersionSchemaVerifier.resource();var mode=TestSchemaMigration.requestedMode(new String[]{"--apply-backup-version-registration"});assertEquals(TestSchemaMigration.Mode.APPLY_BACKUP_VERSION_REGISTRATION,mode);assertTrue(TestSchemaMigration.shouldMigrate(mode,TestSchemaMigration.Plan.BACKUP_ARCHIVE_STAGING_APPLIED));assertFalse(TestSchemaMigration.shouldMigrate(mode,TestSchemaMigration.Plan.BACKUP_VERSION_REGISTRATION_APPLIED));assertFalse(TestSchemaMigration.shouldMigrate(TestSchemaMigration.Mode.READ_ONLY_CHECK,TestSchemaMigration.Plan.BACKUP_VERSION_REGISTRATION_APPLIED));assertThrows(IllegalStateException.class,()->TestSchemaMigration.shouldMigrate(mode,TestSchemaMigration.Plan.BACKUP_RUN_JOURNAL_APPLIED));}
 @Test void exactCatalogRejectsMissingExtraOrAlteredDefinition(){var expected=BackupVersionSchemaVerifier.REGISTRATION_CONSTRAINTS;assertDoesNotThrow(()->BackupVersionSchemaVerifier.requireDefinitions(expected,expected));var missing=new TreeMap<>(expected);missing.pollFirstEntry();assertThrows(IllegalStateException.class,()->BackupVersionSchemaVerifier.requireDefinitions(expected,missing));var extra=new TreeMap<>(expected);extra.put("extra","0".repeat(64));assertThrows(IllegalStateException.class,()->BackupVersionSchemaVerifier.requireDefinitions(expected,extra));var changed=new TreeMap<>(expected);changed.put(changed.firstKey(),"0".repeat(64));assertThrows(IllegalStateException.class,()->BackupVersionSchemaVerifier.requireDefinitions(expected,changed));}
 @Test void registrationRequiresOriginalSourceAndDeferredMatchingSuccess()throws Exception{try(var in=getClass().getResourceAsStream("/db/migration/"+BackupVersionSchemaVerifier.SCRIPT)){assertNotNull(in);String sql=new String(in.readAllBytes(),StandardCharsets.UTF_8);for(String marker:List.of("current_database()<>'mop_test'","UNIQUE(tenant_id,run_id,attempt_number)","DEFERRABLE INITIALLY DEFERRED","Version registration and matching successful run must commit together","FOR UPDATE","transaction_timestamp()","GRANT SELECT,INSERT","CHECK(NOT device_execution_authorized)","CHECK(NOT retention_verified)","CHECK(NOT recovery_verified)","Original verified archive event required"))assertTrue(sql.contains(marker),marker);assertFalse(sql.contains("SECURITY DEFINER"));assertFalse(sql.contains("GRANT UPDATE"));assertFalse(sql.contains("GRANT DELETE"));}}
}
